package org.apache.commons.math.linear;

import java.io.*;
import java.io.Serializable;
import java.math.*;
import java.util.*;
import org.apache.commons.math.exception.MathArithmeticException;
import org.apache.commons.math.exception.util.LocalizedFormats;
import org.apache.commons.math.util.FastMath;
import org.apache.commons.math.util.OpenIntToDoubleHashMap.Iterator;
import org.apache.commons.math.util.OpenIntToDoubleHashMap;
import org.junit.*;
import org.junit.Assert;
import org.junit.Test;
import static org.junit.Assert.*;

/**
 * Unit tests for OpenMapRealVector#append(double[] a)
 */
public class OpenMapRealVector_append_TriageGen1Test {

    @Test
    public void testAppendWithValidArray() {
        // Initialize original vector
        double[] originalData = {1.0, 2.0, 0.0};
        OpenMapRealVector original = new OpenMapRealVector(originalData);

        // Data to append
        double[] toAppend = {3.0, 4.0};

        // Execute append
        OpenMapRealVector result = original.append(toAppend);

        // Verify dimension
        Assert.assertEquals("Dimension should be sum of original and appended", 
                original.getDimension() + toAppend.length, result.getDimension());

        // Verify content
        Assert.assertEquals(1.0, result.getEntry(0), 1e-10);
        Assert.assertEquals(2.0, result.getEntry(1), 1e-10);
        Assert.assertEquals(3.0, result.getEntry(2), 1e-10);
        Assert.assertEquals(4.0, result.getEntry(3), 1e-10);
    }










}

