import static org.junit.Assert.*;

/**
 * Unit tests for OpenMapRealVector#append(double[] a)
 */
public class OpenMapRealVector_append_TriageGen1Test {





    @Test
    public void testAppendWithSparseVector() {
        // Create a sparse vector (only index 0 set)
        OpenMapRealVector original = new OpenMapRealVector(10);
        original.setEntry(0, 5.0);

        double[] toAppend = {6.0, 7.0};
        OpenMapRealVector result = original.append(toAppend);

        Assert.assertEquals(12, result.getDimension());
        Assert.assertEquals(5.0, result.getEntry(0), 1e-10);
        Assert.assertEquals(6.0, result.getEntry(10), 1e-10);
        Assert.assertEquals(7.0, result.getEntry(11), 1e-10);
    }






}

package org.apache.commons.math.linear;

