import org.junit.Test;
import static org.junit.Assert.*;

/**
 * Unit tests for OpenMapRealVector#append(double[] a)
 */
public class OpenMapRealVector_append_TriageGen1Test {









    @Test
    public void testAppendImmutability() {
        // Ensure the original vector is not modified by the append operation
        double[] originalData = {1.0, 1.0};
        OpenMapRealVector original = new OpenMapRealVector(originalData);
        double[] toAppend = {2.0, 2.0};

        original.append(toAppend);

        Assert.assertEquals("Original vector dimension should not change", 2, original.getDimension());
        Assert.assertEquals(1.0, original.getEntry(0), 1e-10);
        Assert.assertEquals(1.0, original.getEntry(1), 1e-10);
    }


}

package org.apache.commons.math.linear;

import java.io.*;
