import java.util.*;
import org.apache.commons.math.exception.MathArithmeticException;
import org.apache.commons.math.exception.util.LocalizedFormats;
import org.apache.commons.math.util.FastMath;
import org.apache.commons.math.util.OpenIntToDoubleHashMap.Iterator;
import org.apache.commons.math.util.OpenIntToDoubleHashMap;
import org.junit.*;
import org.junit.Assert;
import org.junit.Test;
import static org.junit.Assert.*;

/**
 * Unit tests for OpenMapRealVector#append(double[] a)
 */
public class OpenMapRealVector_append_TriageGen1Test {











    @Test
    public void testAppendWithLargeValues() {
        OpenMapRealVector original = new OpenMapRealVector(new double[]{Double.MAX_VALUE});
        double[] toAppend = {Double.MIN_VALUE, 0.0};

        OpenMapRealVector result = original.append(toAppend);

        Assert.assertEquals(Double.MAX_VALUE, result.getEntry(0), 0.0);
        Assert.assertEquals(Double.MIN_VALUE, result.getEntry(1), 0.0);
        Assert.assertEquals(0.0, result.getEntry(2), 0.0);
    }
}
